        assertEquals(cancelled.getAmountPaid(), cancelled.getRefund());
    }

    @Test
    void testCancelNonRefundableReservation() {
        Reservation reservation = reservationService.createReservation(
                "101",
                "João Silva",
                "joao@example.com",
                "12345678901",
                LocalDate.of(2027, 3, 10),
                LocalDate.of(2027, 3, 12),
